# qx2_collatz :: 1
def qx2_collatz(n):
    if n <= 0:
        return 0
    c = 0
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        c += 1
    return c

if __name__ == '__main__':
    print(qx2_collatz(1))

